            for r in range(r1 + 1, r2):
                out[r][c2] = 5
            # Lower arm running back toward the initial column.
            for c in range(c1 + 1, c2):
                out[r2][c] = 5
    # Connect lower anchors 6 and 3 with a horizontal row of 5s.
    if 6 in pos and 3 in pos:
        r6, c6 = pos[6]
        r3, c3 = pos[3]
        if r6 == r3:
