 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    pts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v in (1, 2, 3, 6):
                pts.setdefault(v, []).append((r, c))

    def line(r, c, rr, cc, color=5, include_end=False):
        dr = 0 if rr == r else (1 if rr > r else -1)
        dc = 0 if cc == c else (1 if cc > c else -1)
        y, x = r + dr, c + dc
        while (y, x) != (rr, cc):
            if grid[y][x] == 0:
                out[y][x] = color
            y += dr
            x += dc
        if include_end and grid[rr][cc] == 0:
            out[rr][cc] = color

    # 1: copy two columns right and one row up; 5s bridge horizontally.
    for r, c in pts.get(1, []):
        rr, cc = r - 1, c + 2
        if 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 1
            for x in range(c + 1, cc + 1):
                if grid[r][x] == 0:
                    out[r][x] = 5

    # 2: duplicate four cells left, with a horizontal five bar.
    for r, c in pts.get(2, []):
        cc = c - 4
        if 0 <= cc < w:
            out[r][cc] = 2
            for x in range(cc + 1, c):
                if grid[r][x] == 0:
                    out[r][x] = 5

    # 3: duplicate three rows down, joined by 5s.
    for r, c in pts.get(3, []):
        rr = r + 3
        if rr < h:
            out[rr][c] = 3
            for y in range(r + 1, rr):
                if grid[y][c] == 0:
                    out[y][c] = 5

    # 6: duplicate six rows up, joined by 5s.
    for r, c in pts.get(6, []):
        rr = r - 6
        if rr >= 0:
            out[rr][c] = 6
            for y in range(rr + 1, r):
                if grid[y][c] == 0:
                    out[y][c] = 5

    # When 2 co-occurs with 3 or 6, the center of its bar is a 4, and a
    # diagonal ray of 4s continues down-left to the grid edge.
    if pts.get(2) and (pts.get(3) or pts.get(6)):
        for r, c in pts[2]:
            mid = c - 2
            if 0 <= mid < w:
                out[r][mid] = 4
                y, x = r + 1, mid - 1
                while y < h and x >= 0:
                    out[y][x] = 4
                    y += 1
                    x -= 1
    return out

if __name__ == '__main__':
    d1 = [[0]*10 for _ in range(10)]
    d1[4][3], d1[7][5] = 1, 2
    o1 = transform(d1)
    assert o1[3][5] == 1 and o1[4][4:6] == [5,5]
    assert o1[7][1:6] == [2,5,5,5,2]
    d2 = [[0]*10 for _ in range(10)]
