    o3 = transform(d3)
    assert o3[4][2:7] == [2,5,4,5,2]
    assert [o3[r][4] for r in (2,3,5)] == [3,5,3]
    assert o3[8][0] == 4
    d4 = [[0]*11 for _ in range(11)]
    d4[4][5], d4[6][3], d4[9][7] = 2,6,1
    o4 = transform(d4)
    assert o4[0][3] == 6 and o4[4][1:6] == [2,5,4,5,2]
